import fs from 'node:fs';import {execFileSync} from 'node:child_process';import {pathToFileURL} from 'node:url';
const root=process.cwd(),P='plans/260925-documentation-authority-unification';
const {validateRowSetConservation,loadDecisionShards,validateManualReview}=await import(pathToFileURL(`${root}/scripts/check-doc-inventory-gates.mjs`));
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const registry=read(`${P}/reports/phase-06/working-identity-registry.json`);
const runs=[];for(const prior of [`${P}/reports/identity-registry.json`,`${P}/reports/phase-02-identity-registry.json`])runs.push({prior,findings:validateRowSetConservation(registry,read(prior),prior)});
const shards=[...loadDecisionShards(`${P}/pilot/decisions`),...loadDecisionShards(`${P}/ledger/decisions`)];
const cache=new Map();function reportOf(p,c){const k=`${c}:${p}`;if(!cache.has(k)){try{cache.set(k,execFileSync('git',['show',k],{encoding:'utf8',maxBuffer:5*1024*1024,stdio:['ignore','pipe','ignore']}))}catch{cache.set(k,null)}}return cache.get(k)}
let reviewedRows=0;const findings=[];for(const s of shards)for(const row of [...s.claims,...(s.registryGaps||[])]){if(row.reviewStatus==='reviewed')reviewedRows++;findings.push(...validateManualReview(row,s,reportOf).filter(f=>f.type==='decision-self-review'))}
console.log(JSON.stringify({scope:'Fresh category validators over persisted registry and current decisions; not fresh native identity close',claimIdNotConserved:runs.reduce((n,r)=>n+r.findings.length,0),runs,decisionSelfReview:findings.length,findings,reviewedRows,shards:shards.length},null,2));
